# Purpose: add_entry — auto-annotated by Savant DocSynth
# Added 2025-10-30 19:32:31
def add_entry(scope:str,change_type:str,description:str,status:str="active",author:str="system"):
    """Append immutable context entry"""
    data = read_json(LEDGER,{"history":[],"summary":{}})
    entry = {
        "id": str(uuid.uuid4()),
        "timestamp": utc(),
        "scope": scope,
        "change_type": change_type,
        "description": description,
        "status": status,
        "author": author
    }
    data["history"].append(entry)
    data["summary"] = {
        "total_entries": len(data["history"]),
        "active": len([e for e in data["history"] if e["status"]=="active"]),
        "recent_scope": scope,
        "recent_change": change_type,
        "last_update": utc()
    }
    if LEDGER.exists(): BACKUP.write_text(LEDGER.read_text())
    write_json(LEDGER,data)
    return entry

### — Savant Insight —
# Purpose: build_index — auto-annotated by Savant DocSynth
# Added 2025-10-30 19:32:31
def build_index():
    """Build searchable ledger index"""
    data = read_json(LEDGER,{"history":[]})
    index = {}
    for e in data["history"]:
        s=index.setdefault(e["scope"],[])
        s.append({"id":e["id"],"change":e["change_type"],"time":e["timestamp"]})
    write_json(INDEX,{"generated":utc(),"index":index})
    return index

