### — Savant Insight —
# Purpose: validate_ledger — auto-annotated by Savant DocSynth
# Added 2025-10-30 19:32:31
def validate_ledger():
    """Check coherence, mark anomalies"""
    data=read_json(LEDGER,{"history":[]})
    anomalies=[]
    scopes=set()
    for e in data["history"]:
        if e["scope"] in scopes and e["status"]=="active":
            pass
        scopes.add(e["scope"])
    # Detect duplicates or contradictions
    seen=set()
    for e in data["history"]:
        key=(e["scope"],e["change_type"])
        if key in seen:
            anomalies.append(f"Duplicate context event: {key}")
        seen.add(key)
    # Detect obsolete or conflicting statuses
    for e in data["history"]:
        if "deprecated" in e["description"].lower() and e["status"]=="active":
            anomalies.append(f"Obsolete entry still active: {e['id']}")
    if anomalies:
        LOG.write_text("\n".join([utc()]+anomalies))
        return False, anomalies
    return True, []

### — Savant Insight —
# Purpose: context_doctor — auto-annotated by Savant DocSynth
# Added 2025-10-30 19:32:31
def context_doctor(anomalies):
    """Auto-repair simple contradictions"""
    data=read_json(LEDGER)
    fixed=0
    for e in data["history"]:
        for a in anomalies:
            if e["id"] in a or e["scope"] in a:
                e["status"]="deprecated"
                e["description"]+=" [auto-deprecated]"
                fixed+=1
    if fixed:
        write_json(LEDGER,data)
        build_index()
    return fixed

